use rust_cli_kernel_api::lsp::{LspOperation, LspOutput, LspResultStatus};
use serde_json::{Value, json};

use super::{
    LineReader, Projection, find_symbol_column, project, project_diagnostics, resolve_position,
};
use crate::lsp::runtime::documents::tests::MemoryDisk;
use crate::lsp::runtime::edits::{Diagnostic, Severity, split_lines};

/// Generated by `pnpm rust-agent:lsp-tool:update` from Node's own projection, format and position code.
const GOLDENS: &str = rust_cli_base::include_lf!("../fixtures/lsp_tool_goldens.json");

fn goldens() -> Value {
    serde_json::from_str(GOLDENS).unwrap()
}

fn operation(name: &str) -> LspOperation {
    serde_json::from_value(Value::String(name.to_owned())).unwrap()
}

fn disk(goldens: &Value) -> MemoryDisk {
    let disk = MemoryDisk::default();
    for (path, text) in goldens["files"].as_object().unwrap() {
        disk.put(path, text.as_str().unwrap(), 1);
    }
    disk
}

#[tokio::test]
async fn operation_projections_and_texts_match_node() {
    let goldens = goldens();
    let cases = goldens["operations"].as_array().unwrap();
    assert!(cases.len() >= 21, "every case is generated");
    replay_operations(&goldens, false).await;
}

/// Node's projection with `path.win32` and `fileURLToPath(uri, {windows: true})`: drive letters, encoded colons,
/// special characters, another drive, a UNC share and Windows URI errors.
#[tokio::test]
async fn windows_operation_projections_and_texts_match_node() {
    let goldens = goldens();
    assert_eq!(goldens["win32"]["operations"].as_array().unwrap().len(), 4);
    replay_operations(&goldens["win32"], true).await;
}

async fn replay_operations(goldens: &Value, windows: bool) {
    let disk = disk(goldens);
    let workspace = goldens["workspace"].as_str().unwrap();
    for case in goldens["operations"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let status = match case.get("status").and_then(Value::as_str) {
            Some("pending") => LspResultStatus::Pending,
            _ => LspResultStatus::Ok,
        };
        let input = Projection {
            operation: operation(case["operation"].as_str().unwrap()),
            server_id: "p/ts",
            document_uri: case["documentUri"].as_str().unwrap(),
            workspace,
            windows,
            status,
        };
        let mut reader = LineReader::new(&disk);
        let result = project(&input, &case["raw"], &mut reader).await;
        match case.get("error").and_then(Value::as_str) {
            Some(error) => {
                let failure = result.unwrap_err();
                assert_eq!(failure.message, error, "{name}");
                assert_eq!(failure.code, case["errorCode"], "{name}");
            }
            None => {
                let output = result.unwrap();
                assert_eq!(
                    serde_json::to_value(&output).unwrap(),
                    case["output"],
                    "{name}"
                );
                assert_eq!(
                    output.model_text(),
                    case["text"].as_str().unwrap(),
                    "{name}"
                );
            }
        }
    }
}

fn diagnostic(item: &Value) -> Diagnostic {
    let number = |key: &str| u32::try_from(item[key].as_u64().unwrap()).unwrap();
    Diagnostic {
        line: number("line"),
        character: number("character"),
        end_line: number("endLine"),
        end_character: number("endCharacter"),
        severity: match item["severity"].as_str().unwrap() {
            "error" => Severity::Error,
            "warning" => Severity::Warning,
            "info" => Severity::Info,
            _ => Severity::Hint,
        },
        message: item["message"].as_str().unwrap().to_owned(),
        code: item.get("code").and_then(Value::as_str).map(str::to_owned),
        source: item
            .get("source")
            .and_then(Value::as_str)
            .map(str::to_owned),
    }
}

#[test]
fn diagnostics_projections_and_texts_match_node() {
    let goldens = goldens();
    let workspace = goldens["workspace"].as_str().unwrap();
    for case in goldens["diagnostics"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let items: Vec<Diagnostic> = case["items"]
            .as_array()
            .unwrap()
            .iter()
            .map(diagnostic)
            .collect();
        let status = if case["status"] == "pending" {
            LspResultStatus::Pending
        } else {
            LspResultStatus::Ok
        };
        let output = project_diagnostics("p/ts", "/w/src/a.ts", &items, workspace, false, status);
        assert_eq!(
            serde_json::to_value(&output).unwrap(),
            case["output"],
            "{name}"
        );
        assert_eq!(
            output.model_text(),
            case["text"].as_str().unwrap(),
            "{name}"
        );
    }
}

#[test]
fn windows_diagnostics_projection_and_text_match_node() {
    let goldens = goldens();
    let win32 = &goldens["win32"];
    let case = &win32["diagnostics"];
    let items: Vec<Diagnostic> = case["items"]
        .as_array()
        .unwrap()
        .iter()
        .map(diagnostic)
        .collect();
    let output = project_diagnostics(
        "p/ts",
        case["path"].as_str().unwrap(),
        &items,
        win32["workspace"].as_str().unwrap(),
        true,
        LspResultStatus::Ok,
    );
    assert_eq!(serde_json::to_value(&output).unwrap(), case["output"]);
    assert_eq!(output.model_text(), case["text"].as_str().unwrap());
}

#[test]
fn position_resolution_matches_node() {
    let goldens = goldens();
    let positions = &goldens["positions"];
    let text = positions["text"].as_str().unwrap();
    let lines = split_lines(text);
    assert_eq!(
        json!(lines),
        positions["lines"],
        "the lines split as Node's"
    );
    for case in positions["cases"].as_array().unwrap() {
        let input = &case["input"];
        let result = resolve_position(
            &lines,
            input["line"].as_f64().unwrap(),
            input.get("character").and_then(Value::as_f64),
            input.get("symbol").and_then(Value::as_str),
        );
        match case.get("error") {
            Some(error) => {
                let failure = result.unwrap_err();
                assert_eq!(failure.code, error["code"], "{input}");
                assert_eq!(failure.message, error["message"], "{input}");
            }
            None => {
                let (line, character) = result.unwrap();
                assert_eq!(
                    json!({"line": line, "character": character}),
                    case["output"],
                    "{input}"
                );
            }
        }
    }
}

#[test]
fn a_symbol_overlapping_a_rejected_occurrence_is_found() {
    // The regex tries every start: `a.a` at 1 follows `x`, the one at 3 follows `.`.
    assert_eq!(find_symbol_column("xa.a.a", "a.a"), Some(4));
    assert_eq!(find_symbol_column("use user", "user"), Some(5));
    assert_eq!(find_symbol_column("é1use", "use"), None);
}

#[test]
fn an_empty_output_names_nothing() {
    let output = LspOutput {
        operation: LspOperation::Hover,
        server: "p/ts".to_owned(),
        status: LspResultStatus::Ok,
        locations: None,
        symbols: None,
        hover: None,
        diagnostics: None,
        truncated: false,
        total: None,
    };
    assert_eq!(output.model_text(), "No results");
}

/// ECMAScript `String.prototype.trim` strips exactly WhiteSpace and LineTerminator: the code points below are what
/// Node 26 strips over the whole range. U+0085 (NEL) is White_Space in Unicode but not in ECMAScript.
#[test]
fn js_trim_strips_exactly_what_node_strips() {
    const NODE: &[u32] = &[
        0x9, 0xa, 0xb, 0xc, 0xd, 0x20, 0xa0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004,
        0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
        0xfeff,
    ];
    let stripped: Vec<u32> = (0..=0x10_ffff_u32)
        .filter_map(char::from_u32)
        .filter(|char| super::js_trim(&format!("{char}x")) == "x")
        .map(u32::from)
        .collect();
    assert_eq!(stripped, NODE);
    assert_eq!(super::js_trim("\u{85}x\u{85}"), "\u{85}x\u{85}");
}
